import {basicCameraDirection} from './studio-video-camera.js?v=1';
export function resolveVideoAliases(prompt,refs=[]){const tags=refs.map(r=>String(typeof r==='string'?r:r.tag).replace(/^@/,''));return String(prompt||'').replace(/@((?:image|hinh)(\d+))(?![\p{L}\p{N}_]|-(?!@))/giu,(all,name,n)=>{const index=Number(n)-1;if(index<0||index>=tags.length)throw Error('@'+name+' cần ảnh đầu vào số '+n+', hiện chỉ có '+tags.length+' ảnh.');return '@'+tags[index]})}
export const VIDEO_PRESET_GROUPS={"fashion":{"label":"Người / Thời trang","items":[["fashion1","Đứng nhẹ, chớp mắt","Hold the original editorial pose, subtle breathing through shoulders, one natural blink and a tiny eye-line shift. Keep lips softly closed, expression composed; settle into a clean final still."],["fashion2","Đổi dáng nhẹ","Transfer weight slowly between legs with a small hip/shoulder counter-angle. One hand settles on an existing garment seam; fabric follows with delayed natural motion. Do not invent limbs outside the frame."],["fashion3","Quay đầu nhẹ","Turn the head only 5–10 degrees within the visible angle; eyes follow naturally, chin lowers slightly, then hold. Preserve exact face geometry and hairline; no exaggerated expression."],["fashion4","Gió thổi tóc","A controlled side breeze lifts only loose hair strands and garment edges, then eases. Body remains poised, natural blinking; preserve hairstyle, volume and garment construction."],["fashion5","Vải bay nhẹ","Create a slow ripple through visible silk, pleats or loose fabric, initiated by a small shoulder or wrist movement. Maintain textile pattern, seams and opaque coverage; no wardrobe change."],["fashion6","Bước một bước","If the source shows full body and room to move, take one measured runway step, heel-to-toe weight transfer, then settle. Otherwise use a subtle upper-body weight shift. No walking out of frame."],["fashion7","Chỉnh cổ áo","One visible hand makes a small precise adjustment to an existing lapel, cuff or accessory, then returns to a relaxed pose. Keep finger anatomy and accessory count fixed; never cover the face unnecessarily."],["fashion8","Đổi hướng nhìn","Start with the source gaze; eyes drift briefly toward a plausible off-camera point, then return softly. A slight head tilt complements the gaze; no smile opening the mouth, no wink or flirt exaggeration."],["fashion9","Tạo dáng nghệ thuật","Slowly articulate shoulders and one visible wrist into a restrained sculptural line, keeping torso displacement minimal. Hold negative space and the source silhouette; no dance or rapid gestures."],["fashion10","Ánh sáng trên mặt","Keep the face nearly still while a broad soft highlight glides gently across cheek and hair. Preserve pores, makeup, eye shape and asymmetry. Minimal breathing and blinking, elegant final hold."]]},"product":{"label":"Sản phẩm","items":[["product1","Dải sáng · studio","PRODUCT DIRECTION: A black-flag studio treatment. Preserve the opening exposure for the first beat; a tall diffused reflection then crosses the visible shoulder and front edge, briefly revealing the material before narrowing away. Let the printed face remain readable, with a quiet darker side and a crisp final hero hold. One deliberate light cue, not a glowing outline; no lens flare or added particles."],["product2","Xoay 8° · góc đẹp","PRODUCT DIRECTION: A precision tabletop turn, like a luxury packshot on a geared turntable. Establish the original pose; ease through a single 8-degree turn toward the most readable front-facing angle, decelerate early, then let the final composition breathe. Keep the base planted, reflections physically attached and label plane rigid. No endless rotation, reveal of unseen back labels or camera circling."],["product3","Lơ lửng · sculptural","PRODUCT DIRECTION: Use this only if the source already shows a suspended product. Sustain its exact silhouette while it travels upward by roughly 2% of frame height, then settles into near stillness; a very small shadow response gives weight. Keep orientation fixed, with no tumbling. If the item is grounded, keep it grounded and use a passing foreground shadow instead. No magical levitation from a support."],["product4","Kim loại · điểm lóe","PRODUCT DIRECTION: A restrained jewelry/watch macro treatment applied only to existing reflective details. Begin with deep, clean material contrast; a small off-axis source finds one bevel or gemstone facet, gives a brief precise glint, then falls away into a long quiet beauty hold. Retain brushed grain, real surface imperfections and dark reflections. No sparkle swarm, star filters, chrome recoloring or luminous edges."],["product5","Ngưng tụ · chậm","PRODUCT DIRECTION: A tactile chilled-product study, only on glass or packaging already carrying condensation. One existing bead slowly joins a smaller bead and follows a short gravity-led path; neighboring droplets remain pinned. The highlight catches its edge once, then the movement stops before it obscures print. Keep label ink dry, edges rigid and moisture scale believable. On a dry source use light response alone; do not coat everything in water."],["product6","Kính · khúc xạ","PRODUCT DIRECTION: A transparent-bottle study: allow a broad off-frame light to reveal the thickness of the visible glass and send a soft, imperfect caustic across the existing support. Liquid barely settles, with its original fill line, hue and viscosity unchanged. Progress from calm opening to one luminous material moment and a clean hold. Opaque packaging stays opaque. No internal glow, smoke inside the bottle or changing contents."],["product7","Botanical · nhịp gió","PRODUCT DIRECTION: A real set, not a floral explosion. One visible foreground petal or leaf moves gently through the edge of the composition; secondary foliage responds a fraction later, then settles. Keep the hero product perfectly anchored and its front label unobscured. Retain irregular stems, slight asymmetry and natural texture. Background motion stays lower in contrast than the product. No blooming from nowhere, orbiting ingredients or duplicated leaves."],["product8","Bóng nắng · kiến trúc","PRODUCT DIRECTION: A slow daylight study. Move a single existing soft-edged shadow across the support and lower packaging, as if a flag or leaf just outside the set moved. Maintain the source key-light direction, a fixed contact shadow and restrained highlight roll-off. The rhythm is quiet, one crossing and a long final hold; let negative space remain empty. No time-lapse sky, pulsing exposure or synthetic light tunnel."],["product9","Vải · nếp gấp","PRODUCT DIRECTION: For a product resting on visible silk, paper or soft fabric: send one low-amplitude fold through the foreground, stopping well before it shifts the base. A soft specular seam follows the fold while the product stays still and print remains sharp. Preserve real weave, friction and weighted contact. If no textile is present, animate only a subtle reflection on the existing support. No new drapery or liquid-looking fabric."],["product10","Hero · kết tinh tế","PRODUCT DIRECTION: Build a finished beauty shot from the supplied frame. Keep the product fixed and choose just one cue supported by the set: a broad glass reflection, a single metal glint, or a faint foreground botanical movement. Give the cue a clear arrival and resolution, then reserve the final quarter for a still, readable product with the original negative space. Tactile, controlled contrast and no extra decoration; no end-card text, logo animation, generic bloom or floating particles."]]},"general":{"label":"Dùng cho mọi ảnh","items":[["general1","Ảnh chuyển động nhẹ","Animate the image as a living photograph with only plausible micro-motion: breathing, hair, foliage or reflected light as applicable. Preserve all identities, objects and composition; minimal amplitude, elegant final hold."],["general2","Tạo chiều sâu nhẹ","Create restrained depth separation among existing foreground, subject and background through tiny spatial drift, without moving camera position unless the camera preset requests it. No cardboard cutout edges or invented objects."],["general3","Gió thổi tự nhiên","Apply a gentle breeze only to physically flexible elements already present. Stagger their response and let them settle; rigid products, buildings and anatomy remain stable."],["general4","Ánh sáng thay đổi nhẹ","Vary the existing illumination by a very small smooth amount, preserving exposure, skin tone and material color. No pulsing brightness, flicker, neon color shift or day/night transition."],["general5","Phản chiếu lướt qua","Let existing reflections drift gently across reflective surfaces with physically coherent light motion. Keep object geometry, texture and lettering fixed. Nonreflective scenes use a subtle ambient-light change."],["general6","Hơi nước, mây trôi","Animate only atmosphere visibly supported by the source: faint haze, steam or clouds. If absent, use subtle ambient light instead. Keep the subject unobscured, no added smoke or dramatic particles."],["general7","Chi tiết thiên nhiên","Introduce slow, independent micro-motion to existing natural details such as petals, leaves, water ripples or loose hair. Maintain their original count and shape; no growth, blooming or object transformation."],["general8","Lấy nét chủ thể","Use a subtle controlled depth-of-field transition toward the main subject, ending with it sharp. Keep framing and magnification stable; avoid focus pumping, artificial blur masks and loss of facial detail."],["general9","Một hành động nhỏ","Perform one small physically plausible action suggested by the source pose, then settle. If no safe action is supported, use micro-motion only. No new interaction, props, scene change or exaggerated movement."],["general10","Lặp chuyển động nhẹ","Create a seamless near-still motion cycle with matching opening and closing poses, light and object positions. Use a gentle breath or existing flexible detail; no jump, rewind or obvious reset."]]},"camera":{"label":"Cách quay camera","items":[["camera1","Máy đứng yên","Locked tripod: fixed position, orientation, focal length, crop, horizon and perspective. No pan, tilt, zoom, dolly, orbit, handheld shake or reframing."],["camera2","Máy tiến gần","One straight slow dolly-in, moving physically forward about 3–5% of scene depth. Fixed focal length, centered optical axis, constant camera height, no zoom or orbit. Smooth ease and final hold."],["camera3","Máy lùi xa","One restrained straight dolly-out with fixed focal length and camera height. Reveal only supported image margins; reduce travel rather than invent off-frame geometry. No sudden wide reveal."],["camera4","Máy trượt trái","Slow lateral slider move left, maximum 3–5% frame-width displacement, optical axis and horizon controlled. Natural parallax, no orbit, no zoom, no rotational wobble."],["camera5","Máy trượt phải","Slow lateral slider move right, maximum 3–5% frame-width displacement, fixed focal length and stable height. Preserve source viewing angle as closely as possible; no orbit or whip pan."],["camera6","Máy nâng lên","A tiny vertical camera lift, constant orientation and focal length, subject remains fully framed. No pitch change, crane sweep or exaggerated reveal."],["camera7","Máy hạ xuống","A tiny vertical camera descent with the source camera angle held. Keep horizon and subject scale controlled; no tilt or diving movement."],["camera8","Máy vòng cung nhẹ","A single slow camera arc no greater than 10 degrees around the subject, constant radius and height. Use only supported perspective; reduce motion rather than invent hidden surfaces. No full orbit."],["camera9","Phóng to nhẹ","A very slow optical zoom-in of no more than 5%, camera position and viewing angle fixed. No dolly/parallax, no sudden crop, preserve room around the subject."],["camera10","Chuyển vùng lấy nét","Locked tripod with one deliberate focus pull from a visible foreground detail to the main subject. Position, angle, framing and focal length fixed; no camera translation or focus pumping."]]}};
export const VIDEO_MOTIONS=Object.values(VIDEO_PRESET_GROUPS).flatMap(g=>g.items);
export function videoDirection({motion='general1',camera='camera1',cameraLock=false,cameraPreset=''}){const action=VIDEO_MOTIONS.find(m=>m[0]===motion);const cam=VIDEO_PRESET_GROUPS.camera.items.find(m=>m[0]===camera);if(!action||!cam)throw Error('Chọn preset hợp lệ.');return [action[2],cameraLock?'CAMERA LOCK OVERRIDES ALL OTHER MOTION: fixed camera position, orientation, angle, focal length, framing and horizon. No dolly, pan, tilt, zoom, orbit, parallax from camera or shake. Subject and lighting motion only.':basicCameraDirection(cameraPreset)||cam[2],motion.startsWith('fashion')?'FASHION PERFORMANCE: lips closed and relaxed, no mouth-opening performance, speech, singing, voiceover or lip-sync. Restrained instrumental fashion/art soundtrack, minimal electronic beat and atmospheric texture; no vocals. Preserve identity, anatomy, fabric and styling.':'AUDIO: tasteful restrained instrumental fashion/art ambience, no speech, singing, voiceover or lip-sync.', motion.startsWith('product')?'PRODUCT RHYTHM: first 10% let the opening register; next 60% develop the one selected material/action cue; final 30% resolve and hold. Scale beats to the chosen 5s or 10s duration, no forced slow-motion everywhere. Single shot unless explicit sequence mode. Preserve exact packaging, dimensions, print and real contact. A camera selection complements the cue, never adds another product action.':'PACING: first 15% establish the source frame; middle 65% one continuous restrained motion; last 20% settle and hold. Adapt timing to selected duration. Single shot unless explicit sequence mode. No flicker, morphing, extra limbs, added products or changing labels.','Apply only motions physically supported by the actual image; reduce amplitude or stay still when detail is not visible. Music availability depends on the video model; do not replace visual motion with an audio-only result.'].join('\n')}
export function buildVideoSpec({prompt,refs=[],ratio='16:9',duration=10,motion='general1',camera='camera1',cameraLock=false,mode='animate',applyTools=false,cameraPreset=''}){if(![5,10].includes(Number(duration)))throw Error('Chọn thời lượng 5 hoặc 10 giây.');if(!['16:9','9:16','1:1'].includes(ratio))throw Error('Chọn tỷ lệ video hợp lệ.');if(refs.length<2&&mode==='tvc')mode='animate';prompt=resolveVideoAliases(prompt,refs);const tags=refs.map(r=>r.tag);if(tags.length>5||new Set(tags).size!==tags.length)throw Error('Chọn từ 0 đến 5 ảnh khác nhau.');const allowed=new Set(tags.map(t=>t.toLowerCase()));const mentions=[...String(prompt).matchAll(/@([\p{L}\p{N}_-]+)/gu)].map(m=>m[1]);if(mentions.some(t=>!allowed.has(t.toLowerCase())))throw Error('Prompt còn mã ảnh cũ chưa được chọn. Xóa @mã ảnh cũ hoặc thêm đúng ảnh vào đầu vào.');if(!applyTools){return {mediaType:'video',prompts:[['MUSE VIDEO INPUT CONTRACT. Use ONLY attachments in this message, never old conversations.',`Exactly ${duration} seconds, frame ${ratio}. The selected duration and ratio are authoritative.`,...tags.map((t,i)=>`Attachment ${i+1} = @${t}. Preserve its exact identity, anatomy, costume, objects, environment, palette and original rendering medium, including illustration or 2D style.`),tags.length?'REFERENCE FIDELITY: use each image only for the role and scene assigned by the user. Do not blend different locations, replace characters or invent wardrobe. For ordered multi-frame scripts, follow the specified image order and time ranges; for role references, combine only the assigned roles. Do not impose a single shot, camera lock, music, photorealism, timing structure or a montage unless requested.':'Text-to-video only.', 'AUTHORITATIVE USER SCRIPT (no additional motion preset):',prompt.trim(),...(tags.length===1?['IMAGE TO VIDEO: attachment 1 is the actual opening frame. Animate that image; retain its original rendering style and subjects. Do not deliver a still image.']:[]),...(cameraPreset?['USER-SELECTED CAMERA ONLY: '+basicCameraDirection(cameraPreset)]:[]),'Return one finished video. If detail is not visible in a reference, avoid inventing prominent new details.'].join('\n')],refTags:tags,ratio,duration}};const direction=mode==='tvc'?'TVC EDIT: clean motivated cuts between reference shots; no looping requirement or seamless-loop reset. '+videoDirection({motion:motion==='general10'?'product10':motion,camera,cameraLock,cameraPreset}).replace('Single shot unless explicit sequence mode.','Multiple shots in TVC mode; clean cuts are required.'):videoDirection({motion,camera,cameraLock,cameraPreset});const lines=['MUSE VIDEO INPUT CONTRACT. Use ONLY attachments in THIS message; ignore every image, subject and instruction from earlier conversation.',`MODE: ${mode}. EXACT INPUT COUNT: ${tags.length}. Duration ${duration} seconds; frame ${ratio}.`,...tags.map((t,i)=>`Attached image ${i+1} = @${t}. ${i===0?'Primary visual and starting composition.':['sequence','tvc'].includes(mode)?'Next shot reference in this exact sequence; do not merge people/products.':'Supplementary visual reference only as explicitly requested; never replace primary identity or invent a montage.'}`),mode==='multi'?'Create one coherent cinematic scene using all references according to their assigned roles. Character references fix identity; environment references fix setting; composition references fix framing. Do not turn references into a slideshow or unrelated montage.':tags.length===1?'Animate this ONE image in place. Keep its subject, identity, product geometry, outfit, background and composition. No other source, no cuts or scene changes.':tags.length===0?'Text-to-video only. Do not use any earlier image.':['sequence','tvc'].includes(mode)?'Follow the selected images in order, allocate time across shots. Preserve each shot subject.':'Create ONE coherent shot; image 1 stays primary. Do not automatically animate through all references.',direction,...mode==='tvc'?[`COMPLETE SHORT TVC: exactly ${duration}s total, ONE finished edited film, not four separate files. Use all ${tags.length} current images in order. Divide duration evenly into ${tags.length||1} shots.`,...tags.map((tag,i)=>`SHOT ${i+1}: ${(i*duration/tags.length).toFixed(1)}–${((i+1)*duration/tags.length).toFixed(1)} seconds, animate attached image ${i+1}; ${i===0?'opening hero reveal':i===tags.length-1?'final product beauty hold':'material/context detail'}. Preserve the product visible in that shot; no cross-shot morph.`),'Camera lock applies WITHIN each shot only; cuts to the next selected reference are permitted. No unrelated images, no inherited subjects. Instrumental fashion/art music, no voice or lip-sync.']:[],'USER SCRIPT / MOTION: '+prompt.trim(),'Return one finished video. No unrelated people, products, old references, text overlays or morphing.'];return{mediaType:'video',prompts:[lines.join('\n')],refTags:tags,ratio,duration}}

export function cleanVideoReferences(prompt,refs=[]){return resolveVideoAliases(prompt,refs).trim()}

export function canonicalVideoPrompt(prompt,refs=[]){let text=String(prompt||'').replace(/@hinh(\d+)(?![\p{L}\p{N}_])/giu,(_,n)=>'@image'+n);return text.replace(/@([\p{L}\p{N}_-]+)/gu,(all,tag)=>{const i=refs.findIndex(r=>r.tag.toLowerCase()===tag.toLowerCase());return i>=0?'@image'+(i+1):all})}
